import argparse
import json
import sys
from datetime import datetime

TAX_RATES = {"north": 0.07, "south": 0.05, "east": 0.06, "west": 0.08}


def parse_args():
    parser = argparse.ArgumentParser(
        description="Generate a sales report from a CSV file."
    )
    parser.add_argument("csv_file", metavar="sales.csv", help="CSV file with sales data")
    parser.add_argument(
        "--format",
        choices=("text", "json"),
        default="text",
        help="output format (default: text)",
    )
    parser.add_argument(
        "--since",
        metavar="YYYY-MM-DD",
        help="only include sales on or after this date",
    )
    args = parser.parse_args()

    if args.since is not None:
        try:
            args.since = datetime.strptime(args.since, "%Y-%m-%d").date()
        except ValueError:
            parser.error("--since must be a date in YYYY-MM-DD format")

    return args


def build_report(path, since=None):
    rows = 0
    total_revenue = 0
    total_tax = 0
    by_region = {}
    by_product = {}

    with open(path) as f:
        lines = f.readlines()

    for i in range(len(lines)):
        if i == 0:
            continue
        l = lines[i].strip().split(",")
        if len(l) < 5:
            continue
        if since is not None:
            try:
                sale_date = datetime.strptime(l[0], "%Y-%m-%d").date()
            except ValueError:
                continue
            if sale_date < since:
                continue
        try:
            u = int(l[3])
        except:
            continue
        try:
            pr = float(l[4])
        except:
            continue
        amt = u * pr
        if u >= 50:
            amt = amt - amt * 0.1
        else:
            if u >= 10:
                amt = amt - amt * 0.05
        tx = amt * TAX_RATES.get(l[1], 0)
        total_revenue = total_revenue + amt
        total_tax = total_tax + tx
        if l[1] in by_region:
            by_region[l[1]] = by_region[l[1]] + amt
        else:
            by_region[l[1]] = amt
        if l[2] in by_product:
            by_product[l[2]] = by_product[l[2]] + amt
        else:
            by_product[l[2]] = amt
        rows = rows + 1

    top_product = None
    top_value = 0
    for k in by_product:
        if by_product[k] > top_value:
            top_value = by_product[k]
            top_product = k

    return {
        "rows": rows,
        "total_revenue": total_revenue,
        "total_tax": total_tax,
        "by_region": by_region,
        "by_product": by_product,
        "top_product": top_product,
        "top_value": top_value,
    }


def print_text(report):
    print("SALES REPORT")
    print("============")
    print("Rows: " + str(report["rows"]))
    print("Total revenue: " + str(round(report["total_revenue"], 2)))
    print("Total tax: " + str(round(report["total_tax"], 2)))
    print("")
    print("By region:")
    for k in sorted(report["by_region"].keys()):
        print("  " + k + ": " + str(round(report["by_region"][k], 2)))
    print("")
    print("By product:")
    for k in sorted(report["by_product"].keys()):
        print("  " + k + ": " + str(round(report["by_product"][k], 2)))
    print("")
    best = report["top_product"]
    if best is None:
        print("Top product: None")
    else:
        print("Top product: " + best + " (" + str(round(report["top_value"], 2)) + ")")


def print_json(report):
    data = {
        "rows": report["rows"],
        "total_revenue": round(report["total_revenue"], 2),
        "total_tax": round(report["total_tax"], 2),
        "by_region": {
            k: round(v, 2) for k, v in sorted(report["by_region"].items())
        },
        "by_product": {
            k: round(v, 2) for k, v in sorted(report["by_product"].items())
        },
        "top_product": report["top_product"],
    }
    json.dump(data, sys.stdout, indent=2)
    print("")


def go():
    args = parse_args()
    report = build_report(args.csv_file, args.since)
    if args.format == "json":
        print_json(report)
    else:
        print_text(report)


if __name__ == "__main__":
    go()

